  if (state == DOT_STATE_IDLE) {
    return 1.0;
  }

  if (state == DOT_STATE_LISTENING) {
    return LISTENING_SCALE_FACTOR;
  }

  if (state == DOT_STATE_SPEAKING) {
    return SPEAKING_SCALE_FACTOR;
  }

